INSERT INTO `hazzarah_guard` SELECT 1 FROM DUAL WHERE NOT @hazzarah_ok;

UPDATE `creature_template` SET `ScriptName` = CONVERT(UNHEX('626f73735f68617a7a61726168') USING utf8) WHERE @hazzarah_ok AND (Entry IN (15083,15163)) AND (`Entry` <=> 15083);
UPDATE `creature_spell_list` SET `TargetId` = 105, `Comments` = CONVERT(UNHEX('48617a7a6127726168202d20436861696e204275726e206f6e2052616e646f6d204d616e612055736572') USING utf8) WHERE @hazzarah_ok AND (Id=1508301) AND (`Id` <=> 1508301 AND `Position` <=> 0);
UPDATE `creature_spell_list` SET `TargetId` = 0, `Comments` = CONVERT(UNHEX('48617a7a6127726168202d204172656120536c656570') USING utf8) WHERE @hazzarah_ok AND (Id=1508301) AND (`Id` <=> 1508301 AND `Position` <=> 1);
INSERT INTO `spell_scripts` (`Id`, `ScriptName`) SELECT 24684, CONVERT(UNHEX('7370656c6c5f68617a7a617261685f636861696e5f6275726e') USING utf8) FROM DUAL WHERE @hazzarah_ok AND @count_spell_scripts_0 = 0;

